begin;
create temporary table kk_art_changed(id uuid primary key) on commit drop;
with changed as (
 insert into public.kk_museums as m(id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum)
 select id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum from jsonb_populate_recordset(null::public.kk_museums,'[{"id":"8a290657-e14f-59a2-9b56-0944fdb40844","inventory_key":"wikipedia:Noord-Holland:mocomuseum:amsterdam","name":"Moco Museum","city":"Amsterdam","province":"Noord-Holland","street_address":"Honthorststraat 20","postal_code":"1071 DE","country":"NL","website_url":"https://mocomuseum.com","latitude":null,"longitude":null,"summary":"Ontmoet herkenbare beeldtaal uit moderne en hedendaagse kunst. Moco presenteert bekende namen en wisselende installaties in een villa aan het Museumplein. De nadruk ligt op kunst die snel contact maakt en daarna vragen kan oproepen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["street art","hedendaagse kunst","moderne kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/Modern_Contemporary_%28Moco%29_Museum%2C_Amsterdam_20180702.jpg/1280px-Modern_Contemporary_%28Moco%29_Museum%2C_Amsterdam_20180702.jpg","caption":"Moco Museum — Modern Contemporary (Moco) Museum, Amsterdam 20180702","credit":"Suicasmo","source_url":"https://commons.wikimedia.org/wiki/File:Modern_Contemporary_(Moco)_Museum,_Amsterdam_20180702.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"1562a8b0-4700-5d66-ab3d-249ecc026653","inventory_key":"art-audit:92","name":"Museum Valse kunst","city":"Vledder","province":"Drenthe","street_address":"Brink 1","postal_code":"8381 BE","country":"NL","website_url":"https://www.museumvalsekunst.art","latitude":null,"longitude":null,"summary":"Echt of vals? Dit museum maakt kunstvervalsing tot een intrigerend kijkspel. Naast verhalen over nagebootste meesters ontdek je originele glaskunst en regionale kunst. Je blik op handtekeningen, stijl en authenticiteit krijgt hier een flinke prikkel.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["kunstvervalsing","schilderkunst","glaskunst"],"photos":[],"is_art_museum":true},{"id":"4e9c7be8-3423-5969-9bbe-2fa087de7dea","inventory_key":"museum-nl:fotomuseum-den-haag","name":"Fotomuseum Den Haag","city":"Den Haag","province":"Zuid-Holland","street_address":"Stadhouderslaan 43","postal_code":"2517 HV","country":"NL","website_url":"https://www.fotomuseumdenhaag.nl/","latitude":52.089202,"longitude":4.279849,"summary":"Ontdek hoe verschillend fotografen naar mensen en de wereld kijken. Het Fotomuseum Den Haag presenteert wisselende tentoonstellingen, van historische beelden tot actuele projecten. Bekende namen en minder zichtbaar werk krijgen hier ruimte.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["fotografie","portret","documentaire fotografie"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Photo_Museum_The_Hague%2C_Main_entrance.jpg/1280px-Photo_Museum_The_Hague%2C_Main_entrance.jpg","caption":"Fotomuseum Den Haag — Photo Museum The Hague, Main entrance","credit":"OSeveno","source_url":"https://commons.wikimedia.org/wiki/File:Photo_Museum_The_Hague,_Main_entrance.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"de60456d-84e7-5a70-ba25-d0c58b584e2b","inventory_key":"museum-nl:museum-t-oude-slot","name":"Museum ''t Oude Slot","city":"Veldhoven","province":"Noord-Brabant","street_address":"Hemelrijken 6, Veldhoven","postal_code":"5502 HM","country":"NL","website_url":"https://www.museumoudeslot.nl/","latitude":51.428355,"longitude":5.416652,"summary":"Ontdek de verbeeldingskracht van oude volksprenten. Museum ’t Oude Slot combineert deze beeldverhalen met tentoonstellingen en regionale geschiedenis. Zo krijgt drukwerk dat ooit voor een breed publiek werd gemaakt opnieuw aandacht als beeldende kunst.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["prentkunst","grafiek","volkskunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/63/Zeelst-Veldhoven.jpg/1280px-Zeelst-Veldhoven.jpg","caption":"Museum ''t Oude Slot — Zeelst-Veldhoven","credit":"Kasteelbeer","source_url":"https://commons.wikimedia.org/wiki/File:Zeelst-Veldhoven.jpg","license":"CC BY-SA 3.0 nl"}],"is_art_museum":true},{"id":"514fb72a-7e24-53db-9a2a-88c76c28368f","inventory_key":"museum-nl:museum-krona","name":"Museum Krona","city":"Uden","province":"Noord-Brabant","street_address":"Veghelsedijk 25","postal_code":"5401 PB","country":"NL","website_url":"https://www.museumkrona.nl/nl/","latitude":51.655327,"longitude":5.606799,"summary":"Ontdek de zeggingskracht van religieuze kunst in een kloosteromgeving. Middeleeuwse beelden, kostbare objecten en wisselende tentoonstellingen laten zien hoe kunstenaars geloof verbeelden. Oude werken krijgen hier telkens een nieuwe blik.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["religieuze kunst","middeleeuwse kunst","beeldhouwkunst"],"photos":[{"url":"https://upload.wikimedia.org/wikipedia/commons/a/ae/Uden_-_Museum_voor_Religieuze_Kunst.jpg","caption":"Museum Krona — Uden - Museum voor Religieuze Kunst","credit":"Strikton at Dutch Wikipedia","source_url":"https://commons.wikimedia.org/wiki/File:Uden_-_Museum_voor_Religieuze_Kunst.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"962921a1-f173-54e7-b4fd-6fcdafe873de","inventory_key":"museum-nl:anton-pieck-museum","name":"Anton Pieck Museum","city":"Hattem","province":"Gelderland","street_address":"Noordwal 31","postal_code":"8051 ES","country":"NL","website_url":"https://www.antonpieckmuseum.nl","latitude":52.475458,"longitude":6.067223,"summary":"Ontdek Anton Pieck voorbij de bekende sprookjeswereld. Tekeningen, prenten en schilderijen tonen zijn vakmanschap en oog voor kleine verhalen. Zijn romantische verbeelding krijgt extra diepte wanneer je de vele technieken naast elkaar ziet.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["illustratie","grafiek","kunstenaarsmuseum"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/Hattem%2C_Anton_Pieck_Museum._13-09-2021._%28actm.%29_01.jpg/1280px-Hattem%2C_Anton_Pieck_Museum._13-09-2021._%28actm.%29_01.jpg","caption":"Anton Pieck Museum — Hattem, Anton Pieck Museum. 13-09-2021. (actm.) 01","credit":"Agnes Monkelbaan","source_url":"https://commons.wikimedia.org/wiki/File:Hattem,_Anton_Pieck_Museum._13-09-2021._(actm.)_01.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"823e5b86-eb4d-532d-9fd0-190da04564db","inventory_key":"museum-nl:museum-van-bommel-van-dam","name":"Museum van Bommel van Dam","city":"Venlo","province":"Limburg","street_address":"Keulsepoort 1","postal_code":"5911 BX","country":"NL","website_url":"https://www.vanbommelvandam.nl/","latitude":51.367328,"longitude":6.171284,"summary":"Ontdek schilderijen, tekeningen, fotografie en ruimtelijk werk in Museum van Bommel van Dam. De collectie en wisselende tentoonstellingen brengen vooral moderne en hedendaagse kunstenaars samen. Verschillende vormen van beeldende kunst krijgen hier volop ruimte.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["moderne kunst","hedendaagse kunst","fotografie"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/Museum_Van_Bommel-Venlo-2026.jpg/1280px-Museum_Van_Bommel-Venlo-2026.jpg","caption":"Museum van Bommel van Dam — Museum Van Bommel-Venlo-2026","credit":"Tuxyso","source_url":"https://commons.wikimedia.org/wiki/File:Museum_Van_Bommel-Venlo-2026.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"9f69bc60-5e2e-5d0b-b2ab-65572fba9796","inventory_key":"museum-nl:katwijks-museum","name":"Katwijks Museum","city":"Katwijk","province":"Zuid-Holland","street_address":"Voorstraat 46","postal_code":"2225 ER","country":"NL","website_url":"https://www.katwijksmuseum.nl/","latitude":52.203699,"longitude":4.397068,"summary":"Zie zee, strand en vissersleven door de ogen van kunstenaars die naar Katwijk trokken. Schilderijen uit de kunstenaarskolonie vormen een belangrijk hart van het museum. Kunst en lokale verhalen geven elkaar hier kleur.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["schilderkunst","kunstenaarskolonie","landschap"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f6/Katwijks_Museum_3_dec_2013.JPG/1280px-Katwijks_Museum_3_dec_2013.JPG","caption":"Katwijks Museum — Katwijks Museum 3 dec 2013","credit":"Richardkiwi","source_url":"https://commons.wikimedia.org/wiki/File:Katwijks_Museum_3_dec_2013.JPG","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"3fbea5ae-2cbe-5ed0-96e7-e4c86ab85f88","inventory_key":"museum-nl:coda","name":"CODA","city":"Apeldoorn","province":"Gelderland","street_address":"Vosselmanstraat 299","postal_code":"7311 CL","country":"NL","website_url":"https://www.coda-apeldoorn.nl/","latitude":52.215407,"longitude":5.958447,"summary":"Laat je verrassen door materiaal en verbeelding. CODA presenteert beeldende kunst en design in wisselende tentoonstellingen, met bijzondere aandacht voor sieraden en papierkunst. Wat klein of alledaags lijkt, kan hier een hele wereld openen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","design","papierkunst","sieraden"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/CODA_Centrale_Entree_Apeldoorn_2019.jpg/1280px-CODA_Centrale_Entree_Apeldoorn_2019.jpg","caption":"CODA — CODA Centrale Entree Apeldoorn 2019","credit":"CODA Webmaster","source_url":"https://commons.wikimedia.org/wiki/File:CODA_Centrale_Entree_Apeldoorn_2019.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"4f9e04fd-5c63-54d0-bfb2-9acf614c3501","inventory_key":"museum-nl:project-de-nollen","name":"De Nollen","city":"Den Helder","province":"Noord-Holland","street_address":"Burgemeester Ritmeesterweg 10","postal_code":"1784 NV","country":"NL","website_url":"https://projectdenollen.nl/","latitude":52.9326,"longitude":4.759562,"summary":"Wandel door het kunstlandschap van Ruud van de Wint. Bij De Nollen zijn schilderingen, sculpturen en bouwwerken verbonden met het duin. Licht, ruimte en natuur veranderen je ervaring van de kunst bij iedere stap.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["land art","beeldhouwkunst","kunstenaarsmuseum"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/Den_Helder_-_landschap_De_Nollen.jpg/1280px-Den_Helder_-_landschap_De_Nollen.jpg","caption":"De Nollen — Den Helder - landschap De Nollen","credit":"Lars van der Heide","source_url":"https://commons.wikimedia.org/wiki/File:Den_Helder_-_landschap_De_Nollen.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"afebe6c1-fc16-5e11-b35f-d0a5e5804b92","inventory_key":"museum-nl:van-gogh-village-nuenen","name":"Van Gogh Village Museum","city":"Nuenen","province":"Noord-Brabant","street_address":"Berg 29","postal_code":"5671 CA","country":"NL","website_url":"https://www.vangoghbrabant.com/nl/home/nuenen","latitude":51.476876,"longitude":5.550985,"summary":"Ontdek waarom Nuenen zo belangrijk was voor Van Gogh. Zijn leven, omgeving en ontwikkeling als schilder komen samen in presentaties over zijn Brabantse jaren. Experimenten met licht helpen je zelf beter te kijken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["kunstenaarsmuseum","Vincent van Gogh"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/Van_Gogh_Village_Museum_%282024%29.jpg/1280px-Van_Gogh_Village_Museum_%282024%29.jpg","caption":"Van Gogh Village Museum — Van Gogh Village Museum (2024)","credit":"Remko de Keijzer","source_url":"https://commons.wikimedia.org/wiki/File:Van_Gogh_Village_Museum_(2024).jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"3dc4845e-6524-55d4-9f8c-12d9db984cb9","inventory_key":"museum-nl:museum-collectie-krop","name":"Hildo Krop Museum","city":"Steenwijk","province":"Overijssel","street_address":"Gasthuislaan 2","postal_code":"8331 MX","country":"NL","website_url":"https://hildokrop.nl/","latitude":52.785207,"longitude":6.112336,"summary":"Maak kennis met de veelzijdige Hildo Krop. Zijn sculpturen en ontwerpen laten zien hoe kunst een plaats kreeg in gebouwen en het dagelijks leven. Wisselende accenten in de presentatie belichten telkens een ander deel van zijn oeuvre.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["beeldhouwkunst","Amsterdamse School","kunstenaarsmuseum"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/Rams_Woerthe_Steenwijk.jpg/1280px-Rams_Woerthe_Steenwijk.jpg","caption":"Hildo Krop Museum — Rams Woerthe Steenwijk","credit":"Gouwenaar","source_url":"https://commons.wikimedia.org/wiki/File:Rams_Woerthe_Steenwijk.jpg","license":"Public domain"}],"is_art_museum":true},{"id":"b5ddfbab-b8bd-5856-8b22-792c6464cda1","inventory_key":"museum-nl:musiom","name":"Musiom","city":"Amersfoort","province":"Utrecht","street_address":"Stadsring 137","postal_code":"3817 BA","country":"NL","website_url":"https://musiom.art/","latitude":52.1528796,"longitude":5.3913333,"summary":"Ontdek de uiteenlopende beeldtaal van Nederlandse kunstenaars die vanaf de jaren tachtig hun weg vonden. Musiom biedt een toegankelijke ontmoeting met hedendaagse kunst, in een omgeving waar je rustig kunt kijken en vergelijken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","schilderkunst","beeldhouwkunst"],"photos":[{"url":"https://upload.wikimedia.org/wikipedia/commons/e/e6/Musiom.jpg","caption":"Musiom — Musiom","credit":"H. Boertjens","source_url":"https://commons.wikimedia.org/wiki/File:Musiom.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"f1695613-bc74-5954-a628-c389f55d7e61","inventory_key":"museum-nl:mu-hybrid-art-house","name":"MU Hybrid Art House","city":"Eindhoven","province":"Noord-Brabant","street_address":"Torenallee 40-06","postal_code":"5617 BD","country":"NL","website_url":"https://www.mu.nl","latitude":51.447114,"longitude":5.457005,"summary":"Bij MU kan kunst onverwachte vormen aannemen. Jonge makers en internationale kunstenaars onderzoeken de grenzen tussen disciplines. Wisselende presentaties op Strijp-S nodigen je uit tot nieuwsgierigheid, experiment en een andere blik op morgen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","digitale kunst","experiment"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/MAISON_the_FAUX_-_TIMELESSTIME_MU_Hybrid_Art_House_2023.jpg/1280px-MAISON_the_FAUX_-_TIMELESSTIME_MU_Hybrid_Art_House_2023.jpg","caption":"MU Hybrid Art House — MAISON the FAUX - TIMELESSTIME MU Hybrid Art House 2023","credit":"Hay Kranen","source_url":"https://commons.wikimedia.org/wiki/File:MAISON_the_FAUX_-_TIMELESSTIME_MU_Hybrid_Art_House_2023.jpg","license":"CC BY 4.0"}],"is_art_museum":true},{"id":"fbb5ea54-a7e6-5146-8810-d0aa2e9ba8f1","inventory_key":"museum-nl:museum-eicas","name":"Museum EICAS","city":"Deventer","province":"Overijssel","street_address":"Nieuwe Markt 23","postal_code":"7411 PB","country":"NL","website_url":"https://www.eicas.nl","latitude":52.252551,"longitude":6.154212,"summary":"Ontdek hoe vernieuwend kunst vanaf de jaren zestig kan zijn. EICAS vertrekt vanuit Nul en ZERO, waar materiaal, herhaling en licht nieuwe mogelijkheden openden. Hedendaagse werken laten zien hoe die ideeën blijven doorwerken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["Nul","ZERO","hedendaagse kunst"