nsema, De Stijl en Dada vormen belangrijke lijnen in de collectie. Friese en hedendaagse kunstenaars maken de reis door de twintigste eeuw verder compleet.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["De Stijl","Dada","expressionisme","moderne kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/Museum_open.jpg/1280px-Museum_open.jpg","caption":"Museum Dr8888 — Museum open","credit":"ThamarB","source_url":"https://commons.wikimedia.org/wiki/File:Museum_open.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"878670d8-2c15-529b-8c17-ad3b84455f9a","inventory_key":"museum-nl:vincent-van-goghhuis","name":"Vincent van GoghHuis","city":"Zundert","province":"Noord-Brabant","street_address":"Markt 27","postal_code":"4881 CN","country":"NL","website_url":"https://www.vangoghhuis.com/","latitude":51.472485,"longitude":4.664927,"summary":"Begin bij Van Goghs geboortegrond en ontdek hoe zijn werk kunstenaars blijft inspireren. Het Van GoghHuis vertelt over zijn leven en toont wisselende tentoonstellingen. Nieuwe makers geven zijn nalatenschap steeds een andere richting.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["kunstenaarsmuseum","Vincent van Gogh","hedendaagse kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/P1030605Van_Goghhuis.JPG/1280px-P1030605Van_Goghhuis.JPG","caption":"Vincent van GoghHuis — P1030605Van Goghhuis","credit":"G.Lanting","source_url":"https://commons.wikimedia.org/wiki/File:P1030605Van_Goghhuis.JPG","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"f138ec54-d381-53ff-9f41-d0166c596093","inventory_key":"museum-nl:museum-valkenburg","name":"Museum Land van Valkenburg","city":"Valkenburg (LB)","province":"Limburg","street_address":"Grotestraat Centrum 31","postal_code":"6301 CW","country":"NL","website_url":"https://www.museumlandvanvalkenburg.nl/","latitude":50.863715,"longitude":5.83208,"summary":"Ontdek beeldende kunst uit Valkenburg en het Limburgse heuvelland. Naast streekgeschiedenis presenteert het museum kunstenaars die de omgeving een eigen gezicht geven. Wisselende tentoonstellingen verbinden de regio met nieuwe artistieke perspectieven.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["schilderkunst","regionale kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Valkenburg-Grote_Straat_31_%282%29.JPG/1280px-Valkenburg-Grote_Straat_31_%282%29.JPG","caption":"Museum Land van Valkenburg — Valkenburg-Grote Straat 31 (2)","credit":"Romaine","source_url":"https://commons.wikimedia.org/wiki/File:Valkenburg-Grote_Straat_31_(2).JPG","license":"CC0"}],"is_art_museum":true},{"id":"58e00654-587e-58e6-8fa6-7559430c4734","inventory_key":"museum-nl:oude-kerk","name":"Oude Kerk","city":"Amsterdam","province":"Noord-Holland","street_address":"Oudekerksplein 23","postal_code":"1012 GX","country":"NL","website_url":"https://oudekerk.nl/","latitude":52.374118,"longitude":4.897761,"summary":"Ervaar hoe hedendaagse kunstenaars reageren op een eeuwenoud gebouw. In de Oude Kerk kunnen ruimte, licht en geluid onderdeel van het kunstwerk worden. Tijdelijke presentaties laten je de monumentale omgeving telkens anders beleven.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","installaties","geluidskunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/Amsterdam_Oude_Kerk_2008.jpg/1280px-Amsterdam_Oude_Kerk_2008.jpg","caption":"Oude Kerk — Amsterdam Oude Kerk 2008","credit":"Photo: Andreas Praefcke","source_url":"https://commons.wikimedia.org/wiki/File:Amsterdam_Oude_Kerk_2008.jpg","license":"CC BY 3.0"}],"is_art_museum":true},{"id":"87fe4272-7fd0-585d-a911-c5dc12dbd2f1","inventory_key":"museum-nl:chabot-museum","name":"Chabot Museum","city":"Rotterdam","province":"Zuid-Holland","street_address":"Museumpark 11","postal_code":"3015 CB","country":"NL","website_url":"https://www.chabotmuseum.nl/","latitude":51.91469,"longitude":4.472382,"summary":"Ontmoet het krachtige werk van Henk Chabot. Schilderijen, tekeningen en beelden tonen zijn expressionistische blik op mens en landschap. De lichte museumvilla biedt ruimte om die intensiteit van dichtbij te ervaren.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["expressionisme","schilderkunst","beeldhouwkunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/Chabotmuseum_Rotterdam.jpg/1280px-Chabotmuseum_Rotterdam.jpg","caption":"Chabot Museum — Chabotmuseum Rotterdam","credit":"Choinowski","source_url":"https://commons.wikimedia.org/wiki/File:Chabotmuseum_Rotterdam.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"beeda520-b560-5b4b-890c-5c0b551e09f5","inventory_key":"museum-nl:het-cuypershuis","name":"Het Cuypershuis","city":"Roermond","province":"Limburg","street_address":"Pierre Cuypersstraat 1","postal_code":"6041 XG","country":"NL","website_url":"https://www.cuypershuisroermond.nl/home.html","latitude":51.188337,"longitude":5.988227,"summary":"Ontdek Pierre Cuypers als architect, ontwerper en maker. Tekeningen, maquettes en atelierobjecten laten zien hoe zijn ideeën vorm kregen. Hedendaagse vormgeving legt verrassende verbindingen met het vakmanschap van zijn werkplaatsen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["architectuur","design","kunstenaarsmuseum"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Stedelijk_Museum_Roermond.jpeg/1280px-Stedelijk_Museum_Roermond.jpeg","caption":"Het Cuypershuis — Stedelijk Museum Roermond","credit":"User:Dammit","source_url":"https://commons.wikimedia.org/wiki/File:Stedelijk_Museum_Roermond.jpeg","license":"CC BY-SA 2.5 nl"}],"is_art_museum":true},{"id":"cc320050-d947-5c6d-aa5e-c8f478963bd7","inventory_key":"museum-nl:museum-noordwijk","name":"Museum Noordwijk","city":"Noordwijk","province":"Zuid-Holland","street_address":"Jan Kroonsplein 4","postal_code":"2202 JC","country":"NL","website_url":"https://museumnoordwijk.nl/home/","latitude":52.244286,"longitude":4.431366,"summary":"Kunst en kustleven ontmoeten elkaar in Museum Noordwijk. Ontdek schilderijen, beelden en kleurrijk plateel van De Kroon. De verzameling laat zien hoe kunstenaars en ontwerpers de badplaats een eigen gezicht gaven.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["schilderkunst","keramiek","beeldhouwkunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/Voorgevel_Jan_Kroonsplein_4_%28voorheen_23%29_-_Noordwijk_aan_Zee_-_20169706_-_RCE.jpg/1280px-Voorgevel_Jan_Kroonsplein_4_%28voorheen_23%29_-_Noordwijk_aan_Zee_-_20169706_-_RCE.jpg","caption":"Museum Noordwijk — Voorgevel Jan Kroonsplein 4 (voorheen 23) - Noordwijk aan Zee - 20169706 - RCE","credit":"G.Th. Delemarre","source_url":"https://commons.wikimedia.org/wiki/File:Voorgevel_Jan_Kroonsplein_4_(voorheen_23)_-_Noordwijk_aan_Zee_-_20169706_-_RCE.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"8f6a4ae7-6b90-5430-be60-52601ce16952","inventory_key":"wikipedia:Zuid-Holland:villazebra:rotterdam","name":"Villa Zebra","city":"Rotterdam","province":"Zuid-Holland","street_address":"Stieltjesstraat 21","postal_code":"3071 JV","country":"NL","website_url":"https://www.villazebra.nl/","latitude":null,"longitude":null,"summary":"Kunst wordt een avontuur bij Villa Zebra. Kinderen ontdekken beeldende kunst door te kijken, vragen te stellen en zelf te maken. De wisselende presentaties prikkelen de verbeelding en geven ruimte aan verrassende eigen ideeën.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kinderen","interactief"],"photos":[{"url":"https://upload.wikimedia.org/wikipedia/commons/7/7d/Villa-Zebra-Rotterdam.jpg","caption":"Villa Zebra — Villa-Zebra-Rotterdam","credit":"Josdendaas","source_url":"https://commons.wikimedia.org/wiki/File:Villa-Zebra-Rotterdam.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"8ccd0e05-472e-5b33-ab92-616e197d0f1d","inventory_key":"museum-nl:museum-jan-cunen","name":"Museum Jan Cunen Oss","city":"Oss","province":"Noord-Brabant","street_address":"Molenstraat 65","postal_code":"5341 GC","country":"NL","website_url":"https://www.museumjancunen.nl","latitude":51.765448,"longitude":5.526545,"summary":"Ontdek negentiende-eeuwse en hedendaagse kunst in Villa Constance. Museum Jan Cunen verbindt kunstenaars met de verhalen van Oss en geeft ruimte aan nieuwe makers. De tentoonstellingen nodigen uit om bekende onderwerpen anders te zien.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["schilderkunst","hedendaagse kunst","negentiende eeuw"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Oss_museum.jpg/1280px-Oss_museum.jpg","caption":"Museum Jan Cunen Oss — Oss museum","credit":"M.Minderhoud","source_url":"https://commons.wikimedia.org/wiki/File:Oss_museum.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true}]'::jsonb)
 on conflict(id) do update set inventory_key=excluded.inventory_key,name=excluded.name,city=excluded.city,province=excluded.province,street_address=excluded.street_address,postal_code=excluded.postal_code,country=excluded.country,website_url=excluded.website_url,latitude=excluded.latitude,longitude=excluded.longitude,summary=excluded.summary,operating_status=excluded.operating_status,publication_status=excluded.publication_status,verification_status=excluded.verification_status,tags=excluded.tags,photos=excluded.photos,is_art_museum=excluded.is_art_museum
 where not m.is_art_museum and m.publication_status='draft'
 and not exists(select 1 from kunstkiezer_private.museum_changes c where c.museum_id=m.id and c.editor_id is not null)
 returning id
) insert into kk_art_changed select id from changed;
